import numpy as np

def residues(num, den):
    """Poles of num/den and the residue at each (distinct poles)."""
    poles = np.roots(den)
    res = np.polyval(num, poles) / np.polyval(np.polyder(den), poles)
    return poles, res

def inverse_laplace(num, den, t):
    """Real part of the sum of res * exp(pole * t)."""
    poles, res = residues(num, den)
    return float(np.real(np.sum(res * np.exp(poles * t))))
